window.isFieldVisible=function(t){if(t.style.display==="none"||t.hasAttribute("hidden"))return!1;let e=t.parentElement;for(;e&&e!==document.body;){if(e.style.display==="none"||e.hasAttribute("hidden")||e.classList.contains("hidden")||e.classList.contains("powermail_fieldset")&&e.style.display==="none")return!1;e=e.parentElement}return!0};
